58	 * Concludes the issue: closes an agent-opened one, asks the author to close a
59	 * person-opened one.
60	 *
61	 * Neither branch fails, and the caller ends the session on both. Who opened the
62	 * issue is this function's question to ask, not its caller's to handle — see
63	 * `domain/work/close-request.ts` for the reports that came out of answering it
64	 * the other way.
65	 */
66	export async function concludeIssue(issue: number, reason: string, summary: string): Promise<ConcludeIssueResult> {
67	  const repo = process.env.GITHUB_REPOSITORY ?? "";
68	  // The exit code decides, not just the presence of output. An unread author is
69	  // not a human author: closing the issue outright and telling a person "this was
70	  // opened directly by a human" are different acts, and picking either one on a
71	  // failed lookup asserts something this did not determine. The same question is
72	  // asked fail-loud in `mcp/github.ts` via `ghJsonOrThrow`.
73	  const { code, stdout } = gh("issue", "view", String(issue), "--repo", repo, "--json", "author");
74	  if (code !== 0) {
75	    throw new Error(
76	      `Could not read the author of issue #${issue}, so this cannot tell whether closing it is yours to do.`,
77	    );
78	  }
79	  const authorInfo = stdout ? (JSON.parse(stdout) as GhIssueAuthor) : {};
80	  // Absent field still means "treat as a person", which is the cautious half of
81	  // the pair: it hands the decision to someone rather than taking it.
82	  const isBot = authorInfo.author?.is_bot ?? false;
83	
84	  let body = `Atomaton: the agent on this issue considers its work complete.\n\n**Reason:** ${reason}`;
85	  if (summary) {
86	    body += `\n\n${summary}`;
87	  }
88	
89	  if (!isBot) {
90	    // The request goes above the reason and summary, not after them. It is the
91	    // only sentence in the comment addressed to the person reading it.
92	    body = closeRequestComment({ notify: resolveNotify(repo, issue), body });
93	    mustSucceed(gh("issue", "comment", String(issue), "--repo", repo, "--body", body), `comment on issue #${issue}`);
94	    // stderr, where the tool's own decisions belong. Putting it in the result is
95	    // what put it in the agent's report.
96	    console.error(`close requested: issue=#${issue} (opened by a person, left open for them)`);
97	    return { outcome: "close-requested" };
98	  }
99	
100	  mustSucceed(gh("issue", "comment", String(issue), "--repo", repo, "--body", body), `comment on issue #${issue}`);
101	  mustSucceed(gh("issue", "close", String(issue), "--repo", repo), `close issue #${issue}`);
102	  console.error(`closed: issue=#${issue} (bot-authored)`);
103	  const aggregation = await dispatchOrchestratorIfSubIssueReady(repo, issue);
104	  console.error(describeGateResult(aggregation, issue));
105	  return { outcome: "closed", aggregation };
106	}

